// src/components/Header.js
import React, { useState, useEffect } from "react";

const Header = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userProfile, setUserProfile] = useState(null);
  const [cartCount, setCartCount] = useState(0);

  // Load user data and cart information
  useEffect(() => {
    const token = localStorage.getItem("iibsy_token");

    if (token) {
      // Function to fetch user profile from backend
      const fetchUserProfile = async () => {
        try {
          const response = await fetch("/api/user/profile", {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          });

          if (response.ok) {
            const data = await response.json();
            setUserProfile(data);
            setIsLoggedIn(true);
          } else {
            // Token invalid, clear it
            localStorage.removeItem("iibsy_token");
          }
        } catch (error) {
          console.error("Error fetching user profile:", error);
        }
      };

      // Function to fetch cart data from backend
      const fetchCartData = async () => {
        try {
          const response = await fetch("/api/cart/count", {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          });

          if (response.ok) {
            const data = await response.json();
            setCartCount(data.count);
          }
        } catch (error) {
          console.error("Error fetching cart count:", error);
        }
      };

      fetchUserProfile();
      fetchCartData();
    } else {
      // Check local storage for guest cart
      const guestCart = localStorage.getItem("iibsy_cart");
      if (guestCart) {
        try {
          const cartItems = JSON.parse(guestCart);
          const itemCount = cartItems.reduce(
            (total, item) => total + item.quantity,
            0
          );
          setCartCount(itemCount);
        } catch (e) {
          console.error("Error parsing guest cart:", e);
        }
      }
    }
  }, []);

  const handleLogout = async () => {
    try {
      const token = localStorage.getItem("iibsy_token");
      if (token) {
        await fetch("/api/auth/logout", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
      }
      localStorage.removeItem("iibsy_token");
      setIsLoggedIn(false);
      setUserProfile(null);
      // Redirect to home page or show logged out message
      window.location.href = "/";
    } catch (error) {
      console.error("Error during logout:", error);
    }
  };

  return (
    <header className="fixed w-full bg-snap-light shadow-md z-10">
      <div className="container mx-auto px-4 py-3 flex justify-between items-center">
        <div className="flex items-center">
          {/* iibsy Logo */}
          <a href="/" className="flex items-center">
            <div className="mr-2 w-10 h-10">
              <img
                src="/images/logo.svg"
                alt="iibsy logo"
                className="w-full h-full"
                onError={(e) => {
                  // Fallback to SVG if image fails to load
                  e.target.outerHTML = `<svg
                    viewBox="0 0 100 100"
                    xmlns="http://www.w3.org/2000/svg"
                    className="w-full h-full"
                  >
                    <path
                      d="M98.5,48c-5.4-6.1-48-48-48-48S19.7,14.9,2,36.3s7.3,52.8,7.3,52.8s28.2,9.6,45.8-7.6S98.5,48,98.5,48z"
                      fill="#FF5C4D"
                    />
                    <circle cx="30" cy="78" r="16" fill="#FF5C4D" />
                    <circle cx="80" cy="78" r="16" fill="#FF5C4D" />
                  </svg>`;
                }}
              />
            </div>
            <h1 className="text-3xl font-bold text-snap-red">iibsy</h1>
          </a>
        </div>

        {/* Desktop Navigation */}
        <nav className="hidden md:flex items-center space-x-6">
          <a
            href="#about"
            className="text-snap-dark hover:text-snap-red transition duration-300"
          >
            About
          </a>
          <a
            href="#users"
            className="text-snap-dark hover:text-snap-red transition duration-300"
          >
            For Users
          </a>
          <a
            href="#vendors"
            className="text-snap-dark hover:text-snap-red transition duration-300"
          >
            For Vendors
          </a>
          <a
            href="#contact"
            className="text-snap-dark hover:text-snap-red transition duration-300"
          >
            Contact
          </a>

          {/* Cart Icon */}
          <a href="/cart" className="relative p-1">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              className="h-6 w-6 text-snap-dark hover:text-snap-red transition duration-300"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z"
              />
            </svg>
            {cartCount > 0 && (
              <span className="absolute top-0 right-0 bg-snap-red text-white text-xs font-bold rounded-full h-5 w-5 flex items-center justify-center">
                {cartCount > 9 ? "9+" : cartCount}
              </span>
            )}
          </a>

          {/* Login/Account */}
          {isLoggedIn ? (
            <div className="relative group">
              <button className="flex items-center text-snap-dark hover:text-snap-red transition duration-300">
                <span className="mr-1">
                  {userProfile?.name?.split(" ")[0] || "Account"}
                </span>
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-4 w-4"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M19 9l-7 7-7-7"
                  />
                </svg>
              </button>
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-20 hidden group-hover:block">
                <a
                  href="/dashboard"
                  className="block px-4 py-2 text-snap-gray hover:bg-snap-lightgray hover:text-snap-dark"
                >
                  Dashboard
                </a>
                <a
                  href="/orders"
                  className="block px-4 py-2 text-snap-gray hover:bg-snap-lightgray hover:text-snap-dark"
                >
                  My Orders
                </a>
                <a
                  href="/settings"
                  className="block px-4 py-2 text-snap-gray hover:bg-snap-lightgray hover:text-snap-dark"
                >
                  Settings
                </a>
                <button
                  onClick={handleLogout}
                  className="block w-full text-left px-4 py-2 text-snap-gray hover:bg-snap-lightgray hover:text-snap-dark"
                >
                  Log Out
                </button>
              </div>
            </div>
          ) : (
            <div className="flex items-center space-x-2">
              <a
                href="/login"
                className="text-snap-dark hover:text-snap-red transition duration-300"
              >
                Log In
              </a>
              <a
                href="/register"
                className="bg-snap-red hover:bg-snap-dark text-white px-4 py-2 rounded-md transition duration-300"
              >
                Sign Up
              </a>
            </div>
          )}
        </nav>

        {/* Mobile Menu Button */}
        <div className="md:hidden flex items-center">
          {/* Cart Icon for Mobile */}
          <a href="/cart" className="relative p-1 mr-2">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              className="h-6 w-6 text-snap-dark"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z"
              />
            </svg>
            {cartCount > 0 && (
              <span className="absolute top-0 right-0 bg-snap-red text-white text-xs font-bold rounded-full h-5 w-5 flex items-center justify-center">
                {cartCount > 9 ? "9+" : cartCount}
              </span>
            )}
          </a>

          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="text-snap-dark"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              className="h-6 w-6"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 6h16M4 12h16M4 18h16"
              />
            </svg>
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMenuOpen && (
        <div className="md:hidden bg-snap-light py-2">
          <a
            href="#about"
            className="block text-snap-dark hover:text-snap-red px-4 py-2"
          >
            About
          </a>
          <a
            href="#users"
            className="block text-snap-dark hover:text-snap-red px-4 py-2"
          >
            For Users
          </a>
          <a
            href="#vendors"
            className="block text-snap-dark hover:text-snap-red px-4 py-2"
          >
            For Vendors
          </a>
          <a
            href="#contact"
            className="block text-snap-dark hover:text-snap-red px-4 py-2"
          >
            Contact
          </a>

          {/* User Account Links */}
          {isLoggedIn ? (
            <>
              <div className="border-t border-gray-200 my-2"></div>
              <div className="px-4 py-2 text-snap-gray font-medium">
                Hello, {userProfile?.name?.split(" ")[0] || "User"}
              </div>
              <a
                href="/dashboard"
                className="block text-snap-dark hover:text-snap-red px-4 py-2"
              >
                Dashboard
              </a>
              <a
                href="/orders"
                className="block text-snap-dark hover:text-snap-red px-4 py-2"
              >
                My Orders
              </a>
              <a
                href="/settings"
                className="block text-snap-dark hover:text-snap-red px-4 py-2"
              >
                Settings
              </a>
              <button
                onClick={handleLogout}
                className="block w-full text-left text-snap-dark hover:text-snap-red px-4 py-2"
              >
                Log Out
              </button>
            </>
          ) : (
            <>
              <div className="border-t border-gray-200 my-2"></div>
              <a
                href="/login"
                className="block text-snap-dark hover:text-snap-red px-4 py-2"
              >
                Log In
              </a>
              <a
                href="/register"
                className="block text-snap-dark hover:text-snap-red px-4 py-2"
              >
                Sign Up
              </a>
            </>
          )}
        </div>
      )}
    </header>
  );
};

export default Header;
